// --- 2. InitSchema() - Configuration Schema ---
func (p *ClaudeCodePlugin) InitSchema() *sdk.SchemaInfo {
	schema, err := jsonschema.Reflect(&ClaudeCodeConfig{}).MarshalJSON()
	if err == nil {
		return &sdk.SchemaInfo{Schema: string(schema)}
	}
	return nil
}

// --- 3. Init() - Plugin Initialization ---
func (p *ClaudeCodePlugin) Init(config string) error {
	if os.Getenv("FALCO_CLAUDE_CODE_DEBUG") == "true" {
		debugEnabled = true
		debugLog("Debug mode enabled")
	}

	if config != "" {
		if err := json.Unmarshal([]byte(config), &p.config); err != nil {
			return fmt.Errorf("failed to parse config: %w", err)
		}
	}

	// Buffer size validation (1-100000)
	if p.config.EventBufferSize < 1 || p.config.EventBufferSize > 100000 {
		p.config.EventBufferSize = 1000 // Default
	}

	// Default log path (§27.1)
	if len(p.config.LogPaths) == 0 {
		p.config.LogPaths = []string{"~/.claude/security/events.jsonl"}
	}

	// Initialize parser (claude_code is JSONL → "json" format)
	p.parser = parser.New(parser.Config{
		LogFormat:        "json",
		SecurityPatterns: true,
	})

	debugLog("Initialized with %d log paths, buffer size %d",
		len(p.config.LogPaths), p.config.EventBufferSize)

	return nil
}

// --- 4. Open() - Instance Creation & File Watch Start ---
func (p *ClaudeCodePlugin) Open(params string) (source.Instance, error) {
	watcher, err := fsnotify.NewWatcher()
	if err != nil {
		return nil, fmt.Errorf("failed to create watcher: %w", err)
	}

	instance := &ClaudeCodeInstance{
		eventCh: make(chan *ClaudeCodeEvent, p.config.EventBufferSize),
		watcher: watcher,
		files:   make(map[string]*TailFile),
	}

	for _, logPath := range p.config.LogPaths {
		// Path traversal prevention (E6 security requirement)
		if strings.Contains(logPath, "..") {
			return nil, fmt.Errorf("path traversal not allowed: %s", logPath)
		}

		// ~/path expansion
		if strings.HasPrefix(logPath, "~/") {
			home, err := os.UserHomeDir()
			if err != nil {
				return nil, fmt.Errorf("failed to expand ~/ in path %s: %w", logPath, err)
			}
			logPath = filepath.Join(home, logPath[2:])
		}

		// Ensure parent directory exists (logger may not have created it yet)
		dir := filepath.Dir(logPath)
		if err := os.MkdirAll(dir, 0700); err != nil { // §27.1: directory mode 0700
			debugLog("Warning: failed to create directory %s: %v", dir, err)
		}

		f, err := os.OpenFile(logPath, os.O_RDONLY|os.O_CREATE, 0600) // §27.1: file mode 0600
		if err != nil {
			debugLog("Warning: failed to open %s: %v", logPath, err)
			continue
		}

		// P014: Seek to end so we don't reprocess existing logs on startup.
		// claude_code's events.jsonl accumulates across sessions, so SeekEnd is critical.
		if _, err := f.Seek(0, io.SeekEnd); err != nil {
			debugLog("Warning: failed to seek %s: %v", logPath, err)
		}

		reader := bufio.NewReader(f)
		instance.files[logPath] = &TailFile{
			file:   f,
			path:   logPath,
			reader: reader,
		}

		if err := watcher.Add(dir); err != nil {
			debugLog("Warning: failed to watch %s: %v", dir, err)
		}

		debugLog("Watching: %s", logPath)
	}

	// Start background file reader
	go instance.readLoop(p.parser)

	return instance, nil
}

// readLoop: Background goroutine for reading new log lines
func (inst *ClaudeCodeInstance) readLoop(p *parser.Parser) {
	for {
		select {
		case event, ok := <-inst.watcher.Events:
			if !ok {
				return
			}
			if event.Has(fsnotify.Write) {
				inst.readNewLines(event.Name, p)
			}
		case err, ok := <-inst.watcher.Errors:
			if !ok {
				return
			}
			debugLog("Watcher error: %v", err)
		}
	}
}

// readNewLines: Read and parse new lines from the log file
func (inst *ClaudeCodeInstance) readNewLines(path string, p *parser.Parser) {
	tf, ok := inst.files[path]
	if !ok {
		return
	}

	for {
		line, err := tf.reader.ReadString('\n')
		if err != nil {
			break
		}

		line = strings.TrimSpace(line)
		if line == "" {
			continue
		}

		event := parseLine(line, path, p)
		if event == nil {
			continue
		}

		// Non-blocking channel send (channel overflow handling)
		select {
		case inst.eventCh <- event:
			// Successfully sent
		default:
			// Channel full - drop event and track (FP-012 backpressure)
			dropped := atomic.AddUint64(&inst.droppedEvents, 1)
			if dropped%100 == 0 {
				log.Printf("[claude-code] WARNING: %d events dropped (channel full)", dropped)
			}
		}
	}
}

// parseLine: Parse a log line into a ClaudeCodeEvent
// C-001: LogEntry (parser output) → ClaudeCodeEvent (plugin event) mapping
func parseLine(line, path string, p *parser.Parser) *ClaudeCodeEvent {
	entry, err := p.Parse(line)
	if err != nil {
		debugLog("Parse error: %v (line: %.100s)", err, line)
		return nil
	}

	event := &ClaudeCodeEvent{
		// Common fields
		LogPath:   path,
		Raw:       entry.Raw,
		Timestamp: entry.Timestamp,
		Headers:   entry.Headers, // P004: parser side ensures non-nil

		// ${DOMAIN_FIELDS_MAPPING}
		SchemaVersion:         entry.SchemaVersion,
		ReceivedAt:            entry.ReceivedAt,
		LoggerVersion:         entry.LoggerVersion,
		Host:                  entry.Host,
		User:                  entry.User,
		SessionID:             entry.SessionID,
		TranscriptPath:        entry.TranscriptPath,
		Cwd:                   entry.Cwd,
		PermissionMode:        entry.PermissionMode,
		EventName:             entry.EventName,
		Source:                entry.Source,
		ToolName:              entry.ToolName,
		ToolUseID:             entry.ToolUseID,
		Command:               entry.Command,
		CommandHash:           entry.CommandHash,
		FilePath:              entry.FilePath,
		FileEvent:             entry.FileEvent,
		URL:                   entry.URL,
		Domain:                entry.Domain,
		MCPServerName:         entry.MCPServerName,
		MCPToolName:           entry.MCPToolName,
		MCPScope:              entry.MCPScope,
		PermissionDestination: entry.PermissionDestination,
		PermissionBehavior:    entry.PermissionBehavior,
		RiskType:              entry.RiskType,
		RiskScore:             entry.RiskScore,
		Severity:              entry.Severity,
		Evidence:              entry.Evidence,
		RedactionStatus:       entry.RedactionStatus,
		RawEventSHA256:        entry.RawEventSHA256,
		EventSizeBytes:        entry.EventSizeBytes,
		DurationMs:            entry.DurationMs,
		LatencyMs:             entry.LatencyMs,
		ToolCount:             entry.ToolCount,
		FailureCount:          entry.FailureCount,
		Dropped:               entry.Dropped,
		RawExcerpt:            entry.RawExcerpt,
	}

	return event
}

